from __future__ import annotations

import json
import sys
import uuid
from pathlib import Path
from typing import Any

import httpx

BASE = "https://app.neatlogs.com/api/v1/public"
OUT = Path(__file__).parent / "live"
OUT.mkdir(exist_ok=True)


def env(path: str = r"C:\myspace\hacckathons\kintsugi-omega\.env") -> dict[str, str]:
    values: dict[str, str] = {}
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        if "=" in line and not line.lstrip().startswith("#"):
            k, v = line.split("=", 1)
            values[k.strip()] = v.strip().strip('"').strip("'")
    return values


E = env()
HEADERS = {"Authorization": f"Bearer {E['NEATLOGS_SERVICE_TOKEN']}", "x-project-id": E["NEATLOGS_PROJECT_ID"]}
client = httpx.Client(base_url=BASE, headers=HEADERS, timeout=60)
RL = ("RateLimit-Limit", "RateLimit-Remaining", "X-NeatLogs-RateLimit-Policy", "Retry-After")


def call(method: str, path: str, *, params=None, body=None, save: str | None = None, idem: bool | str = False) -> Any:
    headers = {}
    if idem:
        headers["idempotency-key"] = idem if isinstance(idem, str) else str(uuid.uuid4())
    r = client.request(method, path, params=params, json=body, headers=headers)
    rl = {h: r.headers[h] for h in RL if h in r.headers}
    try:
        data = r.json()
    except Exception:
        data = {"_text": r.text[:500]}
    print(f"{method} {path} {params or ''} -> {r.status_code} {data.get('code', '') if isinstance(data, dict) else ''} {rl}")
    if r.status_code >= 400:
        print("   ", json.dumps(data)[:600])
    if save:
        (OUT / f"{save}.json").write_text(json.dumps({"status": r.status_code, "body": data}, indent=1), encoding="utf-8")
    return data


if __name__ == "__main__":
    method, path = sys.argv[1], sys.argv[2]
    params = json.loads(sys.argv[3]) if len(sys.argv) > 3 and sys.argv[3] else None
    call(method, path, params=params, save=sys.argv[4] if len(sys.argv) > 4 else None)

